// MO2R-style provenance is preserved: explicit content names win; title-only
// guesses remain clearly labeled as fantasy variants, never factual asset scans.
function fallbackLore(target){
 const title=String(target?.name||'Unidentified Mod');
 const sources=[[/(sword|weapon|blade|maul|axe|bow|dagger|staff|spear|armament)/i,'weapon','⚔','#ecbd86','Duelist'],[/(armor|armour|robe|shield|helmet|cloak|outfit|cape)/i,'armor','⛨','#e3b8a1','Ironclad'],[/(follower|companion|npc|voiced)/i,'npc','♟','#d7a7ef','Echo'],[/(creature|wolf|dragon|goblin|troll|beast|werewolf)/i,'creature','♞','#a4dfbd','Broodling'],[/(magic|spell|enchant|rune|storm|frost)/i,'magic','ϟ','#a9c9fd','Hexer'],[/(quest|adventure|chapter|tale|story)/i,'quest','✥','#e9d08d','Oathbreaker'],[/(city|landscape|forest|flora|dungeon|town|world|river)/i,'world','❖','#a5d1b4','Wayfarer'],[/(animation|idle|gesture|pose|motion)/i,'animation','✧','#eeb6cd','Shadow-Dancer']];
 const row=sources.find(x=>x[0].test(title))||[/./,'framework','ᛟ','#b6d7e1','Gremlin'];
 const subject=title.replace(/\b(?:SSE|ESPFE|ESL|SE|AE|NG|2k|4k|8k)\b/gi,'').replace(/\s+/g,' ').trim();
 const bossTitle=`The Unfinished ${subject} ${row[4]}`;
 return {kind:row[1],subject,glyph:row[2],color:row[3],role:row[4],flavor:'An unfinished mod takes a playful monster form.',foes:[`${subject} ${row[4]}`,`Cursed ${subject} ${row[4]}`,`Rogue ${subject} ${row[4]}`],bossTitle,provenance:'title-inference',sourceMod:title};
}
function withLore(t){return {...t,lore:(t&&typeof t.lore==='object'&&Array.isArray(t.lore.foes)&&t.lore.foes.length&&t.lore.bossTitle)?t.lore:fallbackLore(t)}}
function themedFoe(target,serial){
 const t=withLore(target),l=t.lore;
 return {name:String(l.foes[serial%l.foes.length]),kind:l.kind,color:l.color,glyph:l.glyph,source:l.provenance,modId:t.id,sourceMod:t.name};
}
